export async function boardProxy(request){const json=(error,status)=>new Response(JSON.stringify({error}),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});if(request.method!=='POST')return json('Method not allowed.',405);const origin=request.headers.get('Origin');if(origin&&origin!==new URL(request.url).origin)return json('This request must come from the Board page.',403);if(Number(request.headers.get('Content-Length')||0)>4096)return json('Please shorten your decision.',413);let body;try{const text=await request.text();if(text.length>4096)return json('Please shorten your decision.',413);body=JSON.parse(text);}catch{return json('Invalid request body.',400);}const question=typeof body?.question==='string'?body.question.trim():'';if(question.length<8||question.length>500)return json('Please describe your decision in 8 to 500 characters.',400);try{const response=await fetch('https://legacyai.space/api/board',{method:'POST',headers:{'Content-Type':'application/json','Accept':'text/plain'},body:JSON.stringify({question}),signal:AbortSignal.timeout(115000),redirect:'error'});const headers=new Headers({'Content-Type':response.headers.get('content-type')||'text/plain; charset=utf-8','Cache-Control':'no-cache, no-transform','X-Content-Type-Options':'nosniff'});if(response.headers.has('retry-after'))headers.set('Retry-After',response.headers.get('retry-after'));return new Response(response.body,{status:response.status,headers});}catch{return json('The Board could not connect. Please try again shortly or contact Douglas.',502);}}
